// Module 1: Common Anode Seven-Segment Decoder (4-bit BCD to 7-segment) // Common Anode logic: 0 = Segment ON, 1 = Segment OFF // Output mapping: {a, b, c, d, e, f, g} module seg7_decoder ( input logic [3:0] bcd, output logic [6:0] seg ); always_comb begin case (bcd) 4’h0: seg = 7’b0000001; // 0 4’h1: seg = 7’b1001111; // 1 4’h2: seg = 7’b0010010; // 2 4’h3: seg = 7’b0000110; // 3 4’h4: seg = 7’b1001100; // 4 4’h5: seg = 7’b0100100; // 5 4’h6: seg = 7’b0100000; // 6 4’h7: seg = 7’b0001111; // 7 4’h8: seg = 7’b0000000; // 8 4’h9: seg = 7’b0000100; // 9 4’hA: seg = 7’b0001000; // A 4’hB: seg = 7’b1100000; // b 4’hC: seg = 7 me0110001; // C 4’hD: seg = 7’b1000010; // d 4’hE: seg = 7’b0110000; // E 4’hF: seg = 7’b0111000; // F default: seg = 7’b1111111; // Off endcase end endmodule
// Module 2: Time-Multiplexed Dual Seven-Segment Display Controller module seg7_mux_top ( input logic clk, // System clock input logic rst, // Active-high reset input logic [3:0] in0, // First 4-bit BCD input input logic [3:0] in1, // Second 4-bit BCD input output logic [6:0] seg_out, // Cathode segment drive outputs (shared) output logic [1:0] anodes // Common Anodes control (active-low) );
// Clock Divider / Multiplexing Toggle Flag
// For hardware implementation, set counter size to refresh around ~1 kHz to prevent flicker
logic [15:0] refresh_counter;
logic        select_reg;

always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
        refresh_counter &lt;= '0;
        select_reg      &lt;= 1'b0;
    end else begin
        refresh_counter &lt;= refresh_counter + 1'b1;
        select_reg      &lt;= refresh_counter[15]; // Toggles active display
    end
end

// 2-to-1 Multiplexer for BCD inputs
logic [3:0] current_bcd;
assign current_bcd = select_reg ? in1 : in0;

// Single Decoder Instance
seg7_decoder u_decoder (
    .bcd (current_bcd),
    .seg (seg_out)
);

// Active-Low Anode Controller (Enable one display at a time)
// anodes[0] drives Display 0, anodes[1] drives Display 1
assign anodes = select_reg ? 2'b10 : 2'b01;
endmodule
